        static const unsigned short reason[] = { 0, 0 };
        while (!MissionFailed && !MissionSucceeded) {
            Game->NewScriptFrame();
            if (IsActiveThreadTerminating())
                return;
        }
        if (IsActiveThreadTerminating())
            return;
        if (MissionSucceeded) {
            if (IsActiveThreadTerminating())
                return;
            Game->SetQuestAsCompleted(Game->GetActiveQuestName(), true, false, false);
        } else {
