    q.Game = &gsi; q.TermAfter = termAfter; q.TermCalls = 0; q.MissionSucceeded = s0; q.MissionFailed = f0;
    q.WatchForTermination();
    if (std::strcmp(g_log, expect) != 0) { std::printf("got   %s\nwant  %s\n", g_log, expect); return 1; }
